-- 解説が未登録の既存問題（Java / Spring / HTML / SQL）に解説を追加する。
-- 解説が既にある問題は上書きしないため、何度実行しても安全。
SET DEFINE OFF;

UPDATE question SET explanation = 'Java で整数を表す基本型は int です。double は小数を扱う浮動小数点型、char は 1 文字を扱う型です。' WHERE question_id = 1 AND explanation IS NULL;
UPDATE question SET explanation = 'for は繰り返し処理を行う構文です。case は switch 文の分岐、break は繰り返しや switch を途中で抜けるための文です。' WHERE question_id = 2 AND explanation IS NULL;
UPDATE question SET explanation = 'Java の1行コメントは // で書きます。複数行は /* */ で囲みます。# や -- は Java のコメントではありません（-- は SQL のコメントです）。' WHERE question_id = 3 AND explanation IS NULL;
UPDATE question SET explanation = '変数 y は { } の中でだけ有効で、そこで y = 5 + 2 = 7 を出力します。x は外側で宣言されているので、続く出力は 5 です。よって「7 と 5」になります。' WHERE question_id = 4 AND explanation IS NULL;
UPDATE question SET explanation = 'x == 10 は真なので、直後の1文 y = 30 が実行されます。y は 20 から 30 に変わり、30 が出力されます。' WHERE question_id = 5 AND explanation IS NULL;
UPDATE question SET explanation = 'オーバーライドでは、親クラスと同じメソッド名・引数・戻り値の型で子クラスが処理を再定義します。メソッド名だけ同じで引数が違うものはオーバーロードです。' WHERE question_id = 6 AND explanation IS NULL;
UPDATE question SET explanation = 'b++ は現在の値 4 を使ってから b を 5 にします。++a は先に a を 4 にしてから使います。a = 4 + 4 = 8 なので、a + b = 8 + 5 = 13 です。' WHERE question_id = 7 AND explanation IS NULL;
UPDATE question SET explanation = 'i = 1 で x = 1、i = 2 で x = 3 になり、そこで break して繰り返しを抜けます。よって出力は 3 です。' WHERE question_id = 8 AND explanation IS NULL;
UPDATE question SET explanation = 'インターフェースは複数を同時に実装（多重実装）できます。メソッドは基本的に public で、インターフェース自体はインスタンス化できません。' WHERE question_id = 9 AND explanation IS NULL;
UPDATE question SET explanation = 'リクエストを受け取るクラスには @Controller を付けます。@Repository はデータアクセス層、@Autowired は依存性の注入に使います。' WHERE question_id = 10 AND explanation IS NULL;
UPDATE question SET explanation = 'Controller から画面へ値を渡すには Model を使い、addAttribute で名前と値を登録します。Scanner は入力用、StringBuilder は文字列連結用です。' WHERE question_id = 11 AND explanation IS NULL;
UPDATE question SET explanation = 'model.addAttribute は、画面（HTML）で使えるように名前を付けて値を渡す処理です。ここでは empName という名前で従業員名を渡しています。' WHERE question_id = 12 AND explanation IS NULL;
UPDATE question SET explanation = 'Thymeleaf で値を表示するには th:text を使います。th:href は URL 用、th:each は繰り返し用で、用途が異なります。' WHERE question_id = 13 AND explanation IS NULL;
UPDATE question SET explanation = 'BindingResult は検証結果を受け取るため、検証対象の @Valid が付いた引数の直後に書く必要があります。位置がずれると検証エラーを受け取れず、例外になります。' WHERE question_id = 14 AND explanation IS NULL;
UPDATE question SET explanation = 'redirect: は、指定した URL に対してブラウザから再度リクエストを送らせるリダイレクトです。HTML を直接表示するわけではなく、Model の内容も引き継がれません。' WHERE question_id = 15 AND explanation IS NULL;
UPDATE question SET explanation = 'The given id must not be null は、getReferenceById などに null の id を渡したときに出るエラーです。画面から id が送られていない、変数名が違うなどを確認します。' WHERE question_id = 16 AND explanation IS NULL;
UPDATE question SET explanation = 'Entity をそのままセッションに持たせると、DB 管理用の項目やパスワードなど不要な情報まで持ち回ります。必要な情報だけを Bean に詰めて保存するほうが安全で扱いやすくなります。' WHERE question_id = 17 AND explanation IS NULL;
UPDATE question SET explanation = 'session.getAttribute() の戻り値は Object 型です。使うには元の型へのキャスト（型変換）が必要になります。' WHERE question_id = 18 AND explanation IS NULL;
UPDATE question SET explanation = 'ページのタイトルは head 内の title タグで設定します。h1 は本文中の見出し、head は title などを含む領域そのものです。' WHERE question_id = 19 AND explanation IS NULL;
UPDATE question SET explanation = '画像の表示には img タグを使い、src 属性で画像の場所を指定します。image や pic というタグはありません。' WHERE question_id = 20 AND explanation IS NULL;
UPDATE question SET explanation = 'ul の直下には li を置き、li の中に項目を書きます。li の中に ul を入れたり、ul の中に文字を直接書いたりする形は正しくありません。' WHERE question_id = 21 AND explanation IS NULL;
UPDATE question SET explanation = '見出しは h2、箇条書きは ul と li の組合せです。ol は番号付きリストなので不適切です。ul の直下に p を置くのも誤りです。' WHERE question_id = 22 AND explanation IS NULL;
UPDATE question SET explanation = '番号付きリストは ol と li の組合せで作ります。ul は番号なしの箇条書きで、ol の直下に p を置くのも誤りです。' WHERE question_id = 23 AND explanation IS NULL;
UPDATE question SET explanation = 'リンクは a タグで作り、リンク先は href 属性で指定します。link タグは CSS などの外部ファイルを読み込むためのもので、a タグに src 属性はありません。' WHERE question_id = 24 AND explanation IS NULL;
UPDATE question SET explanation = '表は table の中に行 tr を置き、見出しのセルは th、データのセルは td で書きます。th や td は必ず tr の中に入れる必要があります。' WHERE question_id = 25 AND explanation IS NULL;
UPDATE question SET explanation = 'ラベルは label の for と input の id を対応させ、入力欄は input type="text"、送信は button type="submit" で作ります。text や submit という要素はありません。' WHERE question_id = 26 AND explanation IS NULL;
UPDATE question SET explanation = '完全な HTML は DOCTYPE 宣言のあと、head に文字コード（meta charset）と title、body に本文を書きます。title は head 内に置くもので、body 内には置きません。' WHERE question_id = 27 AND explanation IS NULL;
UPDATE question SET explanation = 'UNIX を「含む」行を探すには、前後にワイルドカード % を付けた %UNIX% を指定します。%UNIX は末尾が UNIX、UNIX% は先頭が UNIX の行だけにマッチします。' WHERE question_id = 29 AND explanation IS NULL;
UPDATE question SET explanation = '学生ごとの平均を求めるので GROUP BY 学生番号 とします。集計結果の条件は WHERE ではなく HAVING で指定するため、HAVING AVG(点数) >= 80 になります。' WHERE question_id = 30 AND explanation IS NULL;
UPDATE question SET explanation = '埋込み SQL で、問合せ結果を1行ずつ親プログラムに渡すための仕組みがカーソル（CURSOR）です。ORDER BY は並べ替え、UNION は結果の結合です。' WHERE question_id = 31 AND explanation IS NULL;
UPDATE question SET explanation = '特定の利用者に表への権限を与えるのは GRANT 文です。CONNECT 文は接続のため、CREATE ASSERTION は整合性制約を表明するためのもので、権限付与の手段ではありません。' WHERE question_id = 32 AND explanation IS NULL;
UPDATE question SET explanation = 'GRANT 文は、利用者に対して表への問合せ・更新・追加・削除などの操作権限を付与します。パスワードによる接続制限やビューによる行・列の制限は GRANT 文の説明ではありません。' WHERE question_id = 33 AND explanation IS NULL;
UPDATE question SET explanation = '集計関数と一緒に選択する通常の列は GROUP BY で指定する必要があります。AVG(SUM(数量)) のように集計関数を入れ子にするのも、この形では正しくありません。' WHERE question_id = 34 AND explanation IS NULL;
UPDATE question SET explanation = 'グループ化したあとの件数による絞り込みは HAVING で行います。WHERE の中で集計関数は使えません。HAVING に集計されていない列の条件を置くのも誤りです。' WHERE question_id = 35 AND explanation IS NULL;
UPDATE question SET explanation = 'LEFT JOIN のあとに WHERE で右側の表の列を絞ると、NULL の行が消えて内部結合と同じ結果になります。右側の表の条件は ON に書けば、未解答の顧客も残ります。' WHERE question_id = 36 AND explanation IS NULL;
UPDATE question SET explanation = 'COUNT(列名) は、その列が NULL でない行だけを数えます。10行のうち3行が NULL なので 7 になります。すべての行を数えたいときは COUNT(*) を使います。' WHERE question_id = 37 AND explanation IS NULL;
UPDATE question SET explanation = 'NOT IN の対象に NULL が1つでも含まれると、比較結果が不明（UNKNOWN）になり、結果は 0 件になります。このような場合は NOT EXISTS を使うと安全です。' WHERE question_id = 38 AND explanation IS NULL;
UPDATE question SET explanation = 'Oracle で文字列を連結するには || 演算子を使います。+ は数値の加算用です。CONCAT は引数を2つしか取れないため、3つ以上を連結するにはこの書き方になりません。' WHERE question_id = 39 AND explanation IS NULL;
UPDATE question SET explanation = 'Oracle では降順のとき NULL が先頭に来ます。NULLS LAST を付けると NULL を末尾にできます。WHERE を ORDER BY の中に書くことはできません。' WHERE question_id = 40 AND explanation IS NULL;
UPDATE question SET explanation = 'LIKE の中の % はワイルドカードなので、文字としての % を探すには ESCAPE で指定した文字を前に付けます。LIKE ''%#%'' ESCAPE ''#'' とすると、# の直後の % を文字として扱います。' WHERE question_id = 41 AND explanation IS NULL;
UPDATE question SET explanation = '外側のクエリの列をサブクエリ内で参照する形を、相関サブクエリ（相関副問合せ）と呼びます。外側の1行ごとに内側が評価されます。' WHERE question_id = 42 AND explanation IS NULL;
UPDATE question SET explanation = 'ウィンドウ関数の OVER の中は、PARTITION BY でグループを分け、ORDER BY で順序を指定する順に書きます。ROW_NUMBER() OVER (PARTITION BY user_id ORDER BY ans_time) が正しい書き方です。' WHERE question_id = 43 AND explanation IS NULL;
UPDATE question SET explanation = '更新した行は COMMIT か ROLLBACK するまでロックされるため、別のトランザクションからの更新は待機状態になります。エラーにはならず、上書きもされません。' WHERE question_id = 44 AND explanation IS NULL;
UPDATE question SET explanation = '列に関数や演算を使うとインデックスが使われず、全件走査になりやすくなります。列そのものを範囲で比較する形にすると、インデックスが使えて高速に処理できます。' WHERE question_id = 45 AND explanation IS NULL;
UPDATE question SET explanation = 'EXISTS は条件に合う行を1件見つけた時点で探索を打ち切ります。そのため、サブクエリ側のデータが多いときは IN より速くなる場合があります。' WHERE question_id = 46 AND explanation IS NULL;
UPDATE question SET explanation = '複数の列でグループ化すると、その列の値の組合せごとに1行になります。user_id と question_id の組合せの数が上限で、最大でも元の行数の 10,000 行です。' WHERE question_id = 47 AND explanation IS NULL;
UPDATE question SET explanation = 'Oracle で木構造（階層）を辿る伝統的な構文は START WITH ... CONNECT BY PRIOR ... です。MERGE INTO は更新と挿入をまとめて行う構文です。' WHERE question_id = 48 AND explanation IS NULL;
UPDATE question SET explanation = 'デッドロックは、複数のトランザクションが同じ行を異なる順序でロックしようとして、お互いの解放を待ち続ける現象です。更新の順序をそろえると防ぎやすくなります。' WHERE question_id = 49 AND explanation IS NULL;
UPDATE question SET explanation = '片方のテーブルをメモリ上のハッシュテーブルにして、もう片方と突き合わせる結合方式がハッシュ結合です。大きなテーブル同士の等価結合で使われます。' WHERE question_id = 50 AND explanation IS NULL;
UPDATE question SET explanation = 'GROUP BY がなくても HAVING は書けて、テーブル全体を1つのグループとして扱います。件数が5件より多ければ件数が1行返り、5件以下なら 0 件になります。' WHERE question_id = 51 AND explanation IS NULL;
UPDATE question SET explanation = 'DENSE_RANK は同順位があっても順位を飛ばしません。1位が3人でも次の人は 2位になります。順位を飛ばすのは RANK です（この場合は 4位）。' WHERE question_id = 52 AND explanation IS NULL;
UPDATE question SET explanation = 'B に一致する行がなく B.id が NULL の行は、B.id = C.id の比較で NULL と C.id が一致しないため、C とは結合されません。LEFT JOIN なので行は残り、C の列は NULL になります。' WHERE question_id = 53 AND explanation IS NULL;
UPDATE question SET explanation = 'TRUNCATE は DDL で、ROLLBACK で元に戻せない代わりに、全データを高速に削除できます。DELETE のように1行ずつ処理するわけではなく、外部キーで参照されている表には使えません。' WHERE question_id = 54 AND explanation IS NULL;

COMMIT;
